"""Readable common calculation and compact inline chart from delivered CSVs."""
import json
from pathlib import Path

from build_report import CITY_NAMES, document, esc, link, para, rows, section, table

ROOT = Path(__file__).resolve().parent
NAMES = {**CITY_NAMES, 'DIRECT': 'Из действующих баз'}
ORDER = ['UFA', 'PEE', 'CEK', 'TJM', 'GOJ', 'OMS', 'DIRECT']


def million(value):
    return f'{float(value)/1e6:,.1f}'.replace(',', ' ').replace('.', ',')


def main():
    combined = rows('common_economics/combined_product_comparison.csv')
    baseline = [r for r in rows('common_economics/baseline.csv') if r['demand_scenario'] == 'base']
    base = {r['alternative']: r for r in baseline}
    stress = {(r['network_id'], int(r['fuel_compensation_rub_per_t']), float(r['transfer_keep_fraction'])): r
              for r in rows('common_economics/fixed_schedule_stress.csv')}
    selected = {(r['alternative'], int(r['budget_aircraft'])): r for r in combined
                if r['demand_scenario'] == 'base' and r['mode'] == 'rules500'}
    data = [[NAMES[c]] + [million(selected[c, b]['contribution_rub_year'])
                         if selected[c, b]['status'] == 'ok' else 'Не найдено'
                         for b in range(2, 8)] for c in ORDER]
    body = para('При одинаковом ограничении парка лидер зависит от размера программы. В базовом сценарии при двух самолётах лидирует Омск; при трёх–пяти — Тюмень; при шести–семи — Омск. Это лучшие найденные программы среди шести городов и ограниченного набора прямых рейсов. Полная прибыль и глобальный оптимум не установлены.', 'lead')
    body += para('Бюджет ниже — максимум самолётов вместе с одним резервным. Каждый рабочий самолёт получает до 70 блок-часов в неделю. Разрешены два размера программы: 3–6 либо 8–12 лучей; для прямой сети единица программы — треугольник, а не одно плечо. Выбирается наибольший общий годовой вклад допустимой программы; расходовать весь лимит необязательно. Неиспользованный самолёт не приносит выдуманный доход.')
    body += table(['Город / продукт'] + [f'До {b} самолётов' for b in range(2, 8)], data,
                  'Млн ₽ за условный модельный год, base, экономические ограничения 500 км сохранены; городской фильтр не применяется. Вклад до аренды, полной базы, ввода и оборотных средств.')
    body += para('На пяти самолётах компактная Тюмень даёт 424,0 млн ₽ против 402,6 у Челябинска и 382,0 у Омска. При обязательных 8–12 лучах компактная Тюмень исключается, и на том же ресурсе лидирует Челябинск. На шести самолётах Омск даёт 437,1 млн ₽ против 424,0 у той же компактной Тюмени. Поэтому опубликованные 503,0 млн ₽ Омска на семи самолётах нельзя напрямую сопоставлять с меньшими программами других городов.')
    body += '<h3>Что именно меняет снятие 500 км</h3>'
    body += para('Возврат пяти городов меняет рейтинг критериев, но в экономическом расчёте они уже присутствовали. При снятии порогов в продажах и конечных парах лидерство Тюмени и Омска на указанной сетке сохраняется. У крупной программы Перми вклад растёт на 7,5 млн ₽, до 152,0 млн ₽: модель начинает продавать местные поездки Пермь—Бугульма, ранее обнулённые из-за расстояния 414,6 км. Это возможность внутри модели, а не наблюдение спроса на новый рейс.')
    body += para('У Нижнего Новгорода встречается пропуск алгоритма: при одном запуске без порога он находит семь лучей вместо требуемых восьми, хотя ранее найденный восьмилучевой набор остаётся допустимым. Поэтому сохранены и заново оценены 106 наборов программ. Пометка «не найдено» означает ограниченность этого поиска; она не доказывает невозможность города. Даже отрицательный лучший найденный результат не доказывает отрицательность всех возможных программ.')
    body += '<h3>Два допущения, меняющие знак результата</h3>'
    stress_data = []
    for c in ORDER:
        r = base[c]
        values = [r['contribution_rub_year'],
                  stress[r['network_id'], 3024, 1.0]['contribution_rub_year'],
                  stress[r['network_id'], 32930, .5]['contribution_rub_year']]
        stress_data.append([NAMES[c]] + [million(v) for v in values])
    body += table(['Опубликованная базовая сеть', 'Исходный вклад', 'Компенсация 3 024 ₽/т', 'Осталось 50% пересадок'], stress_data,
                  'Млн ₽/год. Здесь зафиксированы первоначальные сети с их разным парком; это проверка устойчивости каждой сети, не рейтинг на одинаковом ресурсе. Каждый стресс применяется отдельно.')
    body += para('При меньшей топливной компенсации все шесть опубликованных хабов отрицательны. При прежней компенсации сокращение пересадочного потока вдвое также делает их отрицательными. Частоты, местные пассажиры и прочие расходы сохранены; с исчезнувшими поездками исчезают их выручка и пассажирские расходы. Освободившиеся места не перепродаются. Новая сеть под стресс не оптимизируется. Применимость ставок компенсации к Red Wings и будущим периодам не подтверждена; здесь это параметры исходной модели.')
    body += para('Прямой компактный продукт из действующих баз на пяти самолётах даёт 158,8 млн ₽ при исходной компенсации и не зависит от модельных пересадок. Он обходит компактную Тюмень, если сохраняется менее 85,6% её расчётных пересадочных поездок, при равных остальных добавках. Компактная Пермь из трёх лучей также не зависит от пересадок в модели и даёт 56,6 млн ₽ на двух самолётах. Оба плюса исчезают в топливном стрессе. Эти продукты требуют собственной проверки конкуренции, тарифа и доступного парка.')
    body += '<h3>Насколько устойчиво первое место</h3>'
    body += para('На лимите пять самолётов преимущество Тюмени над Челябинском составляет всего 21,5 млн ₽/год; на лимите шесть преимущество Омска над Тюменью — 13,1 млн ₽/год. Дополнительные расходы, различие получаемого тарифа или собственный переток могут поглотить такой запас. Например, при одинаковой дополнительной цене блок-часа преимущество Омска над Тюменью исчезает уже около 2 388 ₽/ч: программа Омска использует больше часов. Это порог при прочих равных, не оценка реальной цены.')
    body += para('Для собственной каннибализации нужен потерянный вклад старого продукта, включая возможность перепродать освободившееся кресло. Текущая модель вычитает старую выручку только на известных точных парах и не оценивает полные сэкономленные затраты. Поэтому нельзя превратить её нулевую «миграцию» в доказательство отсутствия перетока через SVX или московские аэропорты. Новую программу и прямую сеть также нельзя складывать без совместного распределения пассажиров и самолётов.')
    body += '<p class="source">' + ' · '.join(link('common_economics/'+f, label) for f, label in [
        ('report.md', 'Полная методика и результаты'), ('comparison.html', 'Интерактивные ресурсные кривые'),
        ('combined_product_comparison.csv', 'Сопоставимые программы'), ('fixed_schedule_stress.csv', '1 170 стрессов'),
        ('cross_product_thresholds.csv', 'Пороги смены решения')]) + '</p>'
    content = section('economics', 'Сравнение при одинаковом ресурсе', body)
    body = para('На имеющихся данных обоснован возврат всех пяти городов в сравнение. Выбор нового хаба пока не доказан ни для них, ни автоматически для Омска. Рабочее решение — проверять конкретные программы и их преимущество перед использованием того же парка из действующих баз, сохраняя вариант не запускать дополнительную программу.', 'lead')
    body += table(['Вариант', 'Что уже меняет оценку', 'Что должно подтвердить выбор'], [
        ['Уфа', 'Самостоятельный рынок, существующие линии RW и длительный наземный доступ к SVX; условно положительные программы разных размеров', 'Оплачиваемые конечные потоки, собственный переток, корпоративные открытые кресла, местные расходы и место для ТО'],
        ['Пермь', 'Долгий и редкий подвоз; уже есть станция RW; конкретная сезонная программа поддержки', 'Локальный продукт с подтверждёнными тарифом, ресурсом и договорами; для хаба — дополнительный пересадочный спрос'],
        ['Челябинск', 'Существовал статус операционной базы; при пяти самолётах лидирует среди найденных сетей 8–12 лучей', 'Сохранившиеся активы, выбор CEK/SVX и потерянный собственный вклад; для хаба — реальная организация стыковок'],
        ['Тюмень', 'Местное базовое ТО SSJ100 и более сильная компактная программа; частично корпоративный рынок', 'Договорная доступность ТО, открытый оплачиваемый OD и конкурентоспособность против Utair; SJ-100 проверяется отдельно'],
        ['Нижний Новгород', 'Близость Москвы не заменяет анализа конечного маршрута; найденные программы имеют отрицательный вклад', 'Более узкий продукт либо подтверждённые улучшения выручки/затрат; финансирование отрицательного этапа и критерий остановки'],
        ['Омск / действующие базы', 'Омск лидирует при большем ресурсе, но сильно зависит от пересадок; прямой продукт устойчивее к этому отдельному риску', 'Те же проверки OD, тарифа, полного бюджета и календаря; сравнение не может предоставлять контролю более мягкие требования'],
    ])
    body += para('Дальнейшие данные следует собирать по способности изменить решение. Сначала — конечные продажи и выбор аэропорта по ключевым парам, датированное предложение конкурентов и получаемый тариф. Затем — конкретные банки рейсов, календарь введённых и свободных самолётов, местные договорные расходы и подписанная поддержка. Для каждого сценария считаются денежный разрыв этапа, источник его финансирования и наблюдаемый механизм улучшения. Одна общая дата выхода в прибыль без такого расчёта не задаётся.')
    body += para('Новый радиус вместо 500 км не нужен. Для каждой поездки оценивается вероятность выбора аэропорта и маршрута при фактическом времени доступа, цене, частоте и надёжности. Географический, социальный или промышленный фактор входит только через проверяемое влияние на оплачиваемый объём, тариф, расходы или риск. При неизвестных коэффициентах показываются диапазон и порог, при котором меняется выбор.')
    content += section('decision', 'Условия выбора', body)
    (ROOT/'common_synthesis.html').write_text(content)
    chart(combined)
    print(json.dumps({'common_synthesis_bytes': len(content.encode()), 'chart_rows': len(combined)}))


def chart(combined):
    chart_rows = [{k: r[k] for k in ['mode','budget_aircraft','alternative','status','contribution_rub_year']}
                  for r in combined if r['demand_scenario'] == 'base']
    body = '<main class="summary"><h2>Как парк меняет модельного лидера</h2>'
    body += para('Годовой вклад до полных затрат, млн ₽. Шесть городов и прямая программа из действующих баз; разрешены оба размера программы.')
    body += '<div class="controls"><label>Самолётов с резервом <select id="budget">'+''.join(f'<option value="{b}"'+(' selected' if b==5 else '')+f'>{b}</option>' for b in range(2,8))+'</select></label><label>Пороги в расчёте продаж <select id="mode"><option value="rules500">500 км</option><option value="rules0">Сняты</option></select></label></div>'
    body += '<div id="bars" role="img" aria-label="Вклад семи альтернатив"></div><p id="winner" aria-live="polite"></p>'
    body += '<div class="callout">Городской фильтр снят в обоих режимах. Переключатель меняет ограничения продажи коротких поездок внутри экономической модели.</div>'
    body += para('При двух самолётах лидирует Омск; при трёх–пяти — Тюмень; при шести–семи — Омск. Отмена порогов 500 км не меняет этих лидеров. Если требовать минимум восемь лучей, на пяти самолётах лидирует Челябинск.')
    body += para('Это сравнение построенных программ при прежних сценарных тарифах, спросе и топливной компенсации. Расписание по дням, фактические продажи, полные расходы и доступность самолётов не подтверждены. Отрицательный найденный результат не отвергает все продукты города.', 'meta')
    body += '<h2>Что сильнее влияет на решение</h2>'
    body += table(['Проверка', 'Результат'], [
        ['Пересадочный поток уменьшен вдвое', 'Все шесть опубликованных базовых хабов отрицательны при прежнем расписании'],
        ['Топливная компенсация 3 024 вместо 32 930 ₽/т', 'Все шесть опубликованных базовых хабов отрицательны'],
        ['Омск и компактная Тюмень, лимит 6 самолётов', 'Разрыв лишь 13,1 млн ₽/год до неизвестных добавочных расходов'],
    ]) + '</main>'
    body += '''<style>.controls{display:flex;flex-wrap:wrap;gap:14px;margin:18px 0}.controls label{display:flex;gap:6px;align-items:center;flex-wrap:wrap;font-size:14px}select{font:inherit;color:var(--foreground);background:var(--card);border:1px solid var(--border);border-radius:4px;padding:6px}.negative{background:var(--destructive,#bd554d)}.missing{color:var(--muted-foreground)}#winner{font-weight:600}</style>'''
    body += '<script>const data='+json.dumps(chart_rows, ensure_ascii=False)+';const names='+json.dumps(NAMES, ensure_ascii=False)+';const order='+json.dumps(ORDER)+';'
    body += '''function draw(){const chosen=data.filter(r=>r.mode===document.getElementById('mode').value&&r.budget_aircraft===document.getElementById('budget').value);const valid=chosen.filter(r=>r.status==='ok');const max=Math.max(1,...valid.map(r=>Math.abs(Number(r.contribution_rub_year))));const best=valid.reduce((a,b)=>Number(a.contribution_rub_year)>Number(b.contribution_rub_year)?a:b);document.getElementById('bars').innerHTML=order.map(c=>{const r=chosen.find(x=>x.alternative===c);if(r.status!=='ok')return '<div class="bar-row missing"><span>'+names[c]+'</span><span>Не найдено</span><span>—</span></div>';const v=Number(r.contribution_rub_year);return '<div class="bar-row"><span>'+names[c]+'</span><div class="bar-track"><div class="bar-fill '+(v<0?'negative':'')+'" style="width:'+Math.abs(v)/max*100+'%"></div></div><span>'+(v/1e6).toLocaleString('ru-RU',{maximumFractionDigits:1,minimumFractionDigits:1})+'</span></div>'}).join('');document.getElementById('winner').textContent='Лучший найденный вариант: '+names[best.alternative]+'.';}document.querySelectorAll('select').forEach(x=>x.addEventListener('change',draw));draw();</script>'''
    (ROOT/'summary.html').write_text(document('Сравнение городов при одинаковом парке',body))


if __name__ == '__main__':
    main()
